def match(orders):
    import heapq

    buy_heap = []   # entries: (-price, seq, id)
    sell_heap = []  # entries: (price, seq, id)
    info = {}       # id -> {'side':..., 'price':..., 'qty':..., 'active':...}
    seq_counter = 0
    trades = []

    def clean_buy():
        while buy_heap:
            negprice, seq, oid = buy_heap[0]
            rec = info.get(oid)
            if rec is None or (not rec['active']) or rec['qty'] <= 0:
                heapq.heappop(buy_heap)
            else:
                break

    def clean_sell():
        while sell_heap:
            price, seq, oid = sell_heap[0]
            rec = info.get(oid)
            if rec is None or (not rec['active']) or rec['qty'] <= 0:
                heapq.heappop(sell_heap)
            else:
                break

    for order in orders:
        typ = order[0]

        if typ == 'cancel':
            oid = order[1]
            if oid in info and info[oid]['active'] and info[oid]['qty'] > 0:
                info[oid]['active'] = False
            continue

        if typ == 'limit':
            _, oid, side, price, qty = order
        elif typ == 'ioc':
            _, oid, side, price, qty = order
        elif typ == 'market':
            _, oid, side, qty = order
            price = None
        else:
            # unknown order type, ignore
            continue

        info[oid] = {'side': side, 'price': price, 'qty': qty, 'active': True}
        remaining = qty

        if side == 'buy':
            while remaining > 0:
                clean_sell()
                if not sell_heap:
                    break
                sprice, sseq, sid = sell_heap[0]
                if typ != 'market' and price < sprice:
                    break
                srec = info[sid]
                trade_qty = min(remaining, srec['qty'])
                trades.append([oid, sid, sprice, trade_qty])
                remaining -= trade_qty
                srec['qty'] -= trade_qty
                if srec['qty'] == 0:
                    srec['active'] = False
                    heapq.heappop(sell_heap)
            info[oid]['qty'] = remaining
            if typ == 'limit' and remaining > 0:
                seq_counter += 1
                heapq.heappush(buy_heap, (-price, seq_counter, oid))
            else:
                info[oid]['active'] = False

        else:  # side == 'sell'
            while remaining > 0:
                clean_buy()
                if not buy_heap:
                    break
                negprice, bseq, bid = buy_heap[0]
                bprice = -negprice
                if typ != 'market' and price > bprice:
                    break
                brec = info[bid]
                trade_qty = min(remaining, brec['qty'])
                trades.append([bid, oid, bprice, trade_qty])
                remaining -= trade_qty
                brec['qty'] -= trade_qty
                if brec['qty'] == 0:
                    brec['active'] = False
                    heapq.heappop(buy_heap)
            info[oid]['qty'] = remaining
            if typ == 'limit' and remaining > 0:
                seq_counter += 1
                heapq.heappush(sell_heap, (price, seq_counter, oid))
            else:
                info[oid]['active'] = False

    return trades

